'use strict';
const {base,candidate,printer,assert,same,context,cleanup,writeReceipt}=require('./test-support.cjs'),{run,coupon,params}=require('./virtual-task.cjs');
const checks=[],rows=[],shifted=x=>{const m=coupon();m.positions=m.positions.map((q,i)=>i%3===0?q+x:q);m.group='synthetic-shift-'+x;return m;};
